  const equalsIndex = token.indexOf("=");

  if (equalsIndex === -1) {
    return {
      flag: token,
      hasInlineValue: false,
      inlineValue: "",
    };
  }

  return {
    flag: token.slice(0, equalsIndex),
    hasInlineValue: true,
    inlineValue: token.slice(equalsIndex + 1),
  };
}

function buildParseFailure(programName, message) {
  return {
    ok: false,
    exitCode: 2,
    stdout: "",
    stderr: `${buildUsageLine(programName)}\n${programName}: error: ${message}\n`,
  };
