}

export function parseTest8Arguments(argv, programName) {
  if (argv.some(isHelpToken)) {
    return {
      ok: false,
      exitCode: 0,
      stdout: buildHelpText(programName),
      stderr: "",
    };
  }

  const values = Object.create(null);
  const extras = [];

  for (let index = 0; index < argv.length; index += 1) {
    const token = argv[index];

    if (token === "--") {
      extras.push(...argv.slice(index + 1));
      break;
    }

    if (isHelpToken(token)) {
      continue;
