import { parseTest8Arguments } from "./lib/cli/parseArguments.mjs";
import { Bidict } from "./lib/bidict/bidict.mjs";
import { BidictRuntimeError } from "./lib/bidict/errors.mjs";
import { reportRuntimeError } from "./lib/runtime/reportRuntimeError.mjs";

function getProgramName(scriptPath) {
  if (!scriptPath) {
    return "test8.mjs";
  }

  const parts = scriptPath.replaceAll("\\", "/").split("/");
  return parts[parts.length - 1] || "test8.mjs";
}

function writeStdoutLine(value) {
  process.stdout.write(`${value}\n`);
}

function setWithTraceLine(bidictInstance, key, value, scriptLine) {
  try {
    bidictInstance.set(key, value);
  } catch (error) {
    if (error instanceof BidictRuntimeError) {
      error.scriptLine = scriptLine;
    }

    throw error;
  }
}

function main() {
  const programName = getProgramName(process.argv[1]);
  const parsed = parseTest8Arguments(process.argv.slice(2), programName);

  if (!parsed.ok) {
    if (parsed.stdout !== "") {
      process.stdout.write(parsed.stdout);
    }

    if (parsed.stderr !== "") {
      process.stderr.write(parsed.stderr);
    }

    return parsed.exitCode;
  }

  const args = parsed.args;
  const bidictInstance = new Bidict();

  setWithTraceLine(bidictInstance, args.k1, args.v1, 15);
  setWithTraceLine(bidictInstance, args.k2, args.v2, 16);
  setWithTraceLine(bidictInstance, args.k3, args.v3, 17);

  writeStdoutLine(bidictInstance.toString());
  writeStdoutLine(bidictInstance.get(args.k1).toString());
  writeStdoutLine(bidictInstance.getKey(args.v2));
  writeStdoutLine(bidictInstance.getKey(args.v3));

  setWithTraceLine(bidictInstance, args.k1, 999n, 26);
  writeStdoutLine(bidictInstance.toString());

  return 0;
}

try {
  process.exitCode = main();
} catch (error) {
  if (error instanceof BidictRuntimeError) {
    reportRuntimeError(error);
    process.exitCode = 1;
  } else {
    throw error;
  }
}

